def get_sample_df(key):
    """
    Return a sample dataset as a pandas DataFrame.
    key: "upi" | "ads" | "cop"
    """
    import pandas as pd
    if key not in SAMPLES:
        raise ValueError(f"Unknown sample key: {key}. Valid keys: {list(SAMPLES.keys())}")
    return pd.DataFrame(SAMPLES[key]["rows"])


def get_sample_context(key):
    """Return the context description for a sample dataset."""
    if key not in SAMPLES:
        raise ValueError(f"Unknown sample key: {key}")
    return SAMPLES[key]["context"]